-- Generated by scripts/gen_mart_models.py
-- Fixed 2026-09-20: was reading source() with 4 bare try_to_date() calls and
-- 1 bare try_to_number() (CITATION_COUNT) -- epoch-misparse/rounding risk on
-- a 10,070,727-row table. Live-checked: CITATION_COUNT is 100% whole numbers
-- today (10,070,727 filled, 0 fractional) -- clean, landmine not active bug.
-- No staging model exists for this source. Wrapped every bare call with
-- stg_date/stg_int (macros/staging_casts.sql) -- the guard only nulls out
-- pure-digit values with no date separator, so the DATE_FILED epoch-1970
-- investigation below is unaffected (those rows are real dashed dates).

with source as (
    select * from {{ source('ripple_raw', 'FED_COURTLISTENER_OPINION_CLUSTERS') }}
)

select
    ID as id,
    {{ stg_date('"DATE_CREATED"') }} as date_created,
    {{ stg_date('"DATE_MODIFIED"') }} as date_modified,
    JUDGES as judges,
    -- NOT A BUG (epoch-1970 investigation, 2026-08-18): date_filed drives
    -- ~49,791 of 10,070,727 rows (0.5%) landing in 1970, spread across many
    -- distinct 1970 days (confirmed live) -- real federal court opinions filed
    -- that year, not sentinel garbage. Left as-is.
    {{ stg_date('"DATE_FILED"') }} as date_filed,
    -- KNOWN COSMETIC ISSUE, NOT FIXED (epoch-1970 investigation, 2026-08-18):
    -- DATE_FILED_IS_APPROXIMATE is a boolean flag ('t'/'f'), not a date --
    -- same semantic-mismatch class as the bugs fixed elsewhere in this batch,
    -- but it silently returns NULL rather than epoch-1970 garbage, so it
    -- contributes 0 rows to the epoch count and corrupts nothing. Flagged for
    -- the record, not treated as part of this fix batch: the right output
    -- type is a boolean, not a date, but there's no live defect (bad date
    -- values) forcing a fix today.
    nullif(trim(DATE_FILED_IS_APPROXIMATE), '') as date_filed_is_approximate,
    SLUG as slug,
    CASE_NAME_SHORT as case_name_short,
    CASE_NAME as case_name,
    CASE_NAME_FULL as case_name_full,
    SCDB_ID as scdb_id,
    SCDB_DECISION_DIRECTION as scdb_decision_direction,
    SCDB_VOTES_MAJORITY as scdb_votes_majority,
    SCDB_VOTES_MINORITY as scdb_votes_minority,
    SOURCE as source,
    PROCEDURAL_HISTORY as procedural_history,
    ATTORNEYS as attorneys,
    NATURE_OF_SUIT as nature_of_suit,
    POSTURE as posture,
    SYLLABUS as syllabus,
    HEADNOTES as headnotes,
    SUMMARY as summary,
    DISPOSITION as disposition,
    HISTORY as history,
    nullif(trim(OTHER_DATES), '') as other_dates,
    CROSS_REFERENCE as cross_reference,
    CORRECTION as correction,
    {{ stg_int('"CITATION_COUNT"') }} as citation_count,
    PRECEDENTIAL_STATUS as precedential_status,
    {{ stg_date('"DATE_BLOCKED"') }} as date_blocked,
    BLOCKED as blocked,
    FILEPATH_JSON_HARVARD as filepath_json_harvard,
    FILEPATH_PDF_HARVARD as filepath_pdf_harvard,
    DOCKET_ID as docket_id,
    ARGUMENTS as arguments,
    HEADMATTER as headmatter
